def can_move(current, next_pos, visited):
    if next_pos in visited:
        return False
    x, y = next_pos
    if x < 0 or x >= len(current) or y < 0 or y >= len(current[0]):
        return False
    return True

def find_path(maze, start, end):
    queue = [(start, [start])]
    visited = set([start])
    while queue:
        current, path = queue.pop(0)
        if current == end:
            return path
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            next_pos = (current[0] + dx, current[1] + dy)
            if can_move(maze, next_pos, visited):
                visited.add(next_pos)
                queue.append((next_pos, path + [next_pos]))
    return None

